const encoder = new TextEncoder();
const SECURITY = {'X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','X-Frame-Options':'SAMEORIGIN','Permissions-Policy':'camera=(), microphone=(), geolocation=()','Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' blob: data:; connect-src 'self'; media-src 'self' https: blob:; frame-src 'self' https://www.youtube-nocookie.com https://player.vimeo.com https://open.spotify.com https://w.soundcloud.com; frame-ancestors 'self'; base-uri 'none'; form-action 'self'"};
function reply(body,status=200,headers={}) {return new Response(body,{status,headers:{...SECURITY,'Cache-Control':'no-store',...headers}});}
function json(data,status=200,headers={}) {return reply(JSON.stringify(data),status,{'Content-Type':'application/json; charset=utf-8',...headers});}
function fail(message,status=400) {const e=new Error(message);e.status=status;throw e;}
const b64 = bytes => btoa(String.fromCharCode(...new Uint8Array(bytes))).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');
const unb64 = value => Uint8Array.from(atob(value.replaceAll('-','+').replaceAll('_','/')),c=>c.charCodeAt(0));
async function hmacKey(secret) {return crypto.subtle.importKey('raw',encoder.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign','verify']);}
function passwordReady(env) {return typeof env.ADMIN_PASSWORD==='string' && env.ADMIN_PASSWORD.length>=16;}
async function auth(request,env) {
  if(!passwordReady(env)) return false;
  const value = request.headers.get('Cookie')?.split(';').map(x=>x.trim()).find(x=>x.startsWith('__Host-portfolio='))?.slice(17);
  if(!value) return false;
  const [expires,nonce,signature,...rest]=value.split('.');
  if(rest.length || !/^\d{10,13}$/.test(expires) || !/^[a-zA-Z0-9_-]{20,40}$/.test(nonce||'') || !signature || Number(expires)<Date.now() || Number(expires)>Date.now()+28800000) return false;
  try {return await crypto.subtle.verify('HMAC',await hmacKey(env.ADMIN_PASSWORD),unb64(signature),encoder.encode(expires+'.'+nonce));} catch {return false;}
}
let readyDB;
async function database(env) {
  if(!env.DB) fail('The Cloudflare D1 database binding DB has not been configured.',503);
  if(!readyDB) readyDB=env.DB.batch([
    env.DB.prepare('CREATE TABLE IF NOT EXISTS content (id INTEGER PRIMARY KEY CHECK(id=1), json TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, updated TEXT NOT NULL)'),
    env.DB.prepare('CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY, mime TEXT NOT NULL, bytes BLOB NOT NULL, size INTEGER NOT NULL, created TEXT NOT NULL)'),
    env.DB.prepare('CREATE TABLE IF NOT EXISTS media_chunks (id TEXT NOT NULL, part INTEGER NOT NULL, bytes BLOB NOT NULL, PRIMARY KEY(id,part))'),
    env.DB.prepare('CREATE TABLE IF NOT EXISTS login_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL)')
  ]).then(()=>env.DB.prepare('INSERT INTO content(id,json,revision,updated) VALUES(1,?,1,?) ON CONFLICT(id) DO NOTHING').bind(JSON.stringify(DEFAULT_CONTENT),new Date().toISOString()).run()).catch(e=>{readyDB=undefined;throw e;});
  await readyDB;return env.DB;
}
async function body(request,limit) {
  if(Number(request.headers.get('Content-Length'))>limit) fail('This upload is too large.',413);
  const reader=request.body?.getReader();if(!reader)return new Uint8Array();
  const chunks=[];let length=0;
  while(true){const {done,value}=await reader.read();if(done)break;length+=value.length;if(length>limit){await reader.cancel();fail('This upload is too large.',413);}chunks.push(value);}
  const bytes=new Uint8Array(length);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}return bytes;
}
async function readJSON(request,limit=1500000) {if(!request.headers.get('Content-Type')?.startsWith('application/json'))fail('Expected JSON.',415);try{return JSON.parse(new TextDecoder().decode(await body(request,limit)));}catch(e){if(e.status)throw e;fail('Invalid JSON.');}}
function text(value,max=2000) {if(typeof value!=='string'||value.length>max)fail('A text field is missing or too long.');return value;}
function url(value) {text(value,500);if(!value)return '';try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password)fail('Links must use https://.');return u.href;}catch{fail('Enter a valid https:// link.');}}
function image(value) {text(value,200);if(!/^\/scenes\/[a-z-]+\.svg$/.test(value)&&!/^\/api\/media\/[a-f0-9-]{36}$/.test(value))fail('Choose a built-in scene or upload a picture.');return value;}
function attachment(value){text(value,200);if(value&&!/^\/api\/files\/[a-f0-9-]{36}$/.test(value))fail('Choose an uploaded attachment.');return value;}
function validatedMedia(value){text(value,1000);const result=mediaSource(value);if(result===null)fail('Choose uploaded media or an HTTPS media link.');return result;}
function validatedEmbed(value){text(value,2000);if(!value)return '';const embed=normalizeEmbed(value);if(!embed)fail('Use a YouTube, Vimeo, Spotify, or SoundCloud link or iframe embed.');return embed.url;}
function number(value,fallback,min,max){if(value===undefined)return fallback;if(typeof value!=='number'||!Number.isFinite(value)||value<min||value>max)fail('A design setting is out of range.');return value;}
function color(value,fallback){if(value===undefined)return fallback;if(typeof value!=='string'||!/^#[0-9a-f]{6}$/i.test(value))fail('Choose a six-digit color.');return value;}
function choice(value,fallback,choices){if(value===undefined)return fallback;if(!choices.includes(value))fail('Choose a supported design option.');return value;}
function flag(value,fallback){if(value===undefined)return fallback;if(typeof value!=='boolean')fail('Invalid toggle setting.');return value;}
function linkItems(items=[]){if(!Array.isArray(items)||items.length>30)fail('Use at most 30 links per group.');return items.map(item=>({label:text(item.label,100),url:url(item.url||''),icon:choice(item.icon,'link',iconChoices),symbol:text(item.symbol||'',8),image:item.image?image(item.image):'',place:{x:number(item.place?.x,0,-500,500),y:number(item.place?.y,0,-500,500),size:number(item.place?.size,24,12,96)}}));}
function design(input={}){const out={};for(const mode of ['dark','light']){out[mode]={};for(const key of Object.keys(appearance[mode]))out[mode][key]=color(input[mode]?.[key],appearance[mode][key]);}
for(const [key,min,max]of [['fontSize',11,24],['headingSize',40,160],['titleSize',24,80],['pageWidth',700,1800],['gap',16,140],['stagger',0,250],['cardSpacing',12,160],['radius',0,60],['texture',0,100],['rings',0,100],['backgroundPosition',0,100],['backgroundY',0,100],['backgroundScale',50,300]])out[key]=number(input[key],appearance[key],min,max);
for(const key of ['headingFont','bodyFont'])out[key]=choice(input[key],appearance[key],fonts);
out.defaultTheme=choice(input.defaultTheme,'dark',['dark','light']);out.layout=choice(input.layout,'staggered',['staggered','grid','single','canvas']);
for(const key of ['motion','showMark','showThemeToggle'])out[key]=flag(input[key],appearance[key]);out.backgroundImage=input.backgroundImage?image(input.backgroundImage):'';out.backgroundFixed=flag(input.backgroundFixed,true);out.backgroundFit=choice(input.backgroundFit,'cover',['cover','contain']);return out;}
